  try {
    const { email } = req.body;
    res.json({ ok: true, email });                                         // 4. response
  } catch (err) {
    next(err);                                                             // or the error handler
  }
});

app.use((err, req, res, next) => res.status(500).json({ message: 'Server error' }));
