const { Kafka } = require('kafkajs');
const kafka = new Kafka({ clientId: 'shop-api', brokers: ['localhost:9092'] });

// Producer (inside the checkout route)
const producer = kafka.producer();
await producer.connect();
await producer.send({ topic: 'order.created', messages: [{ key: order.id, value: JSON.stringify(order) }] });

// Consumer (a separate worker process)
const consumer = kafka.consumer({ groupId: 'email-service' });
await consumer.connect();
await consumer.subscribe({ topic: 'order.created' });
await consumer.run({ eachMessage: async ({ message }) => sendOrderEmail(JSON.parse(message.value)) });

// Express behind a proxy (Render, Heroku): force HTTPS and secure cookies
app.set('trust proxy', 1);
app.use((req, res, next) => {
  if (req.secure) return next();
  res.redirect(301, `https://${req.headers.host}${req.originalUrl}`);
});

