// npm i ioredis
const Redis = require('ioredis');
const redis = new Redis(process.env.REDIS_URL);
const WINDOW = 60 * 1000;

app.post('/api/heartbeat', async (req, res) => {
  const id = String(req.body.visitorId).slice(0, 64);
  await redis.zadd('online', Date.now(), id);
  res.sendStatus(204);
});

app.get('/api/online', async (req, res) => {
  const since = Date.now() - WINDOW;
  await redis.zremrangebyscore('online', '-inf', since);   // drop old visitors
  const count = await redis.zcount('online', since, '+inf');
  res.set('Cache-Control', 'public, max-age=5').json({ count });
});

// Cursor pagination for the feed
app.get('/api/feed', protect, async (req, res) => {
  const limit = Math.min(Number(req.query.limit) || 20, 50);
  const filter = { audience: req.user.id };
  if (req.query.after) filter._id = { $lt: req.query.after };

  const items = await FeedItem.find(filter)
    .sort({ _id: -1 })
    .limit(limit + 1)
    .populate('post');

  const hasMore = items.length > limit;
  const page = items.slice(0, limit);
  res.json({ items: page, nextCursor: hasMore ? page[page.length - 1]._id : null });
});
